tools.example:
resize_pblock pb_core -add {CLOCKREGION_X2Y3:CLOCKREGION_X3Y4}
resize_pblock pb_core -add {RAMB36_X3Y20:RAMB36_X4Y39}
resize_pblock pb_slr1_logic -replace -add {SLR1}
report_utilization -pblocks [get_pblocks pb_core]

foreach pb [get_pblocks] {
  puts "$pb: [get_property GRID_RANGES $pb]"
}
get_pblocks -of_objects [get_cells u_core]

(* keep = "true" *) reg [7:0] state_dbg;
# or in XDC after elaboration
set_property KEEP true [get_nets -hier state_dbg*]

(* ram_style = "ultra" *) reg [71:0] line_buf [0:4095];
# XDC applied to the elaborated design
set_property RAM_STYLE distributed [get_cells u_ctrl/small_lut_ram_reg]

tools.usage:
set_property USE_DSP yes|no|logic|simd [get_cells <cell>]
(* use_dsp = "yes" *) module accumulator (...);
(* use_dsp = "no" *) wire [47:0] sum = a + b;

tools.example:
(* use_dsp = "yes" *) reg [47:0] acc;
always @(posedge clk) acc <= acc + (a * b);
# XDC on a whole hierarchy
set_property USE_DSP no [get_cells u_addr_gen]

(* shreg_extract = "no" *) reg [2:0] data_pipe;
always @(posedge clk) data_pipe <= {data_pipe[1:0], din};
# or for a whole hierarchy in XDC
set_property SHREG_EXTRACT no [get_cells u_high_speed_pipe]

(* fsm_encoding = "one_hot", fsm_safe_state = "reset_state" *) reg [3:0] state;
# global control
synth_design -top top -fsm_extraction one_hot
